package fakes

import (
	"context"

	"evalfixture/domain"
	"evalfixture/repository"
)

// FakeUserRepository is a transparent in-memory implementation: assigned IDs
// are a deterministic function of the input ("user-" + email) so tests can
// assert on both sides.
type FakeUserRepository struct {
	users map[string]*domain.User
}

func NewFakeUserRepository() *FakeUserRepository {
	return &FakeUserRepository{users: make(map[string]*domain.User)}
}

func (r *FakeUserRepository) Save(_ context.Context, user *domain.User) (*domain.User, error) {
	saved := domain.RehydrateUser("user-"+user.Email(), user.Email(), user.OrgID())
	r.users[saved.Email()] = saved
	return saved, nil
}

func (r *FakeUserRepository) GetByEmail(_ context.Context, email string) (*domain.User, error) {
	user, ok := r.users[email]
	if !ok {
		return nil, repository.ErrNotFound
	}
	return user, nil
}

package fakes_test

import (
	"testing"

	"evalfixture/repository/contract"
	"evalfixture/repository/fakes"
)

func TestFakeUserRepository(t *testing.T) {
	contract.RunUserRepositoryContract(t, fakes.NewFakeUserRepository())
}

package contract

import (
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"

	"evalfixture/domaintest"
	"evalfixture/repository"
)

// RunUserRepositoryContract verifies any UserRepository implementation. Run it
// against every fake AND the real implementation so the fake can't drift.
func RunUserRepositoryContract(t *testing.T, repo repository.UserRepository) {
	t.Helper()
	ctx := t.Context()

	t.Run("assigns an id when saving", func(t *testing.T) {
		user := domaintest.NewUnpersistedUser(domaintest.WithEmail("save@example.com"))

		saved, err := repo.Save(ctx, user)

		require.NoError(t, err)
		assert.NotEmpty(t, saved.ID())
	})

	t.Run("retrieves a saved user by email", func(t *testing.T) {
		user := domaintest.NewUnpersistedUser(
			domaintest.WithEmail("contract@example.com"),
			domaintest.WithOrgID("org-42"),
		)
		_, err := repo.Save(ctx, user)
		require.NoError(t, err)

		found, err := repo.GetByEmail(ctx, "contract@example.com")

		require.NoError(t, err)
		assert.Equal(t, "contract@example.com", found.Email())
		assert.Equal(t, "org-42", found.OrgID())
	})

	t.Run("returns ErrNotFound for an unknown email", func(t *testing.T) {
		_, err := repo.GetByEmail(ctx, "nobody@example.com")

		assert.ErrorIs(t, err, repository.ErrNotFound)
	})
}

