	return &User{email: email, orgID: orgID, passwordHash: passwordHash}
}

func RehydrateUser(id, email, orgID, passwordHash string) *User {
	return &User{id: id, email: email, orgID: orgID, passwordHash: passwordHash}
}

func (u *User) ID() string           { return u.id }
func (u *User) Email() string        { return u.email }
func (u *User) OrgID() string        { return u.orgID }
func (u *User) PasswordHash() string { return u.passwordHash }

