	_ = s.service.Register(s.ctx, "alice@example.com", "org-1", "p@ssw0rd")

	user, err := s.users.GetByEmail(s.ctx, "alice@example.com")
	s.Require().NoError(err)
	s.Equal("hashed:p@ssw0rd", user.PasswordHash())
}

