package service

import (
	"context"
	"errors"
	"fmt"
	"time"

	"evalfixture/domain"
	"evalfixture/hasher"
	"evalfixture/repository"
)

var ErrInvalidCredentials = errors.New("invalid credentials")

// Session grants access until ExpiresAt.
type Session struct {
	Email     string
	ExpiresAt time.Time
}

type AccessService struct {
	users      repository.UserRepository
	hasher     hasher.Hasher
	sessionTTL time.Duration
}

func NewAccessService(users repository.UserRepository, h hasher.Hasher, sessionTTL time.Duration) *AccessService {
	return &AccessService{users: users, hasher: h, sessionTTL: sessionTTL}
}

func (s *AccessService) Register(ctx context.Context, email, orgID, password string) error {
	_, err := s.users.Save(ctx, domain.NewUserWithPassword(email, orgID, s.hasher.Hash(password)))
	return err
}

func (s *AccessService) Login(ctx context.Context, email, password string) (Session, error) {
	user, err := s.users.GetByEmail(ctx, email)
	if err != nil {
		return Session{}, ErrInvalidCredentials
	}
	return Session{
		Email:     user.Email(),
		ExpiresAt: time.Now().Add(s.sessionTTL),
	}, nil
}

func (s *AccessService) GrantSession(ctx context.Context, email string) (Session, error) {
	user, err := s.users.GetByEmail(ctx, email)
	if err != nil {
		return Session{}, fmt.Errorf("granting session: %w", err)
	}
	return Session{
		Email:     user.Email(),
		ExpiresAt: time.Now().Add(s.sessionTTL),
	}, nil
}

func (s *AccessService) IsSessionValid(session Session) bool {
	return !session.ExpiresAt.Before(time.Now())
}
